/* Painel integrado: comparar e revisar não modifica as três fontes. */
(()=>{'use strict';const C=MartinsConferencia,J=MartinsJornada,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);const panel=document.createElement('details');panel.id='mcf-panel';panel.innerHTML='<summary>Conferência de divergências por período</summary><p>Compare previsão, presença e documentos por funcionário, obra e dia. Revisar registra uma justificativa; não corrige horas nem aprova RDO. Ausência sem execução não exige RDO.</p><label>De <input id="mcf-start" type="date"></label><label>Até <input id="mcf-end" type="date"></label><button id="mcf-day" type="button">Usar dia selecionado no planejamento</button><button id="mcf-update" type="button">Conferir período (até 31 dias)</button><label>Funcionário <select id="mcf-person"><option value="">Todos</option></select></label><label>Obra <select id="mcf-work"><option value="">Todas</option></select></label><label><input id="mcf-only" type="checkbox"> Somente divergências</label><p id="mcf-status" role="status" aria-live="polite"></p><p id="mcf-warnings" style="white-space:pre-wrap"></p><div style="overflow:auto"><table><thead><tr><th>Revisar</th><th>Data</th><th>Funcionário / ID</th><th>Obra</th><th>Planejado</th><th>Frequência</th><th>RDO aprovado</th><th>Rascunho</th><th>Situação / motivos</th><th>Revisão</th></tr></thead><tbody id="mcf-rows"></tbody></table></div><h3>Detalhes da linha selecionada</h3><p id="mcf-detail" style="white-space:pre-wrap"></p><label>Decisão de conferência <select id="mcf-decision"><option value="conferido">Conferido — sem alterar as fontes</option><option value="aguardando_correcao">Aguardando correção na origem</option></select></label><label>Justificativa (10 a 1000 caracteres)<textarea id="mcf-reason" rows="3" minlength="10" maxlength="1000" style="width:100%;border:1px solid #aaa;padding:10px"></textarea></label><button id="mcf-review" type="button">Registrar revisão local</button><p>Registro permitido a Master ou Engenharia com login local explícito. Isso não substitui autorização no servidor.</p><h3>Histórico da linha</h3><div id="mcf-history" style="white-space:pre-wrap"></div><button id="mcf-csv" type="button">Baixar CSV das linhas filtradas</button><p>O CSV contém apenas a conferência visível. Fotos e notas privadas do RDO não são incluídas.</p>';$('mj-dialog').append(panel);
let report=null,list=[],snap=null,reviewSnapshot=null,selected=null,busy=false;const sources=[J.KEYS.plans,J.KEYS.frequency,J.KEYS.rdos,'cm_colaboradores_db'];const say=s=>$('mcf-status').textContent=s;
function current(){return Object.fromEntries(sources.map(key=>[key,localStorage.getItem(key)]));}
function unchanged(){if(report&&($('mcf-start').value!==report.start||$('mcf-end').value!==report.end))throw Error('Período alterado. Atualize a conferência.');if(!snap||P.canonical(current())!==P.canonical(snap)||reviewSnapshot!==localStorage.getItem(C.KEY))throw Error('As fontes ou o histórico mudaram. Atualize a conferência antes de registrar ou exportar.');P.guard(localStorage,J.KEYS.rdos);}
const run=fn=>()=>{try{fn();}catch(e){say(e.message);}};
function visible(){return report?.lines.filter(r=>(!$('mcf-person').value||r.funcionarioId===$('mcf-person').value)&&(!$('mcf-work').value||r.obra===$('mcf-work').value)&&(!$('mcf-only').checked||r.situacao==='Conferir divergência'))||[];}
function details(){const row=report?.lines.find(r=>r.key===selected);$('mcf-detail').textContent=row?'Data: '+row.data+'\nFuncionário: '+row.nome+' / '+row.funcionarioId+'\nObra: '+row.obra+'\nFrequência: '+row.statusFrequencia+'\n'+(row.motivos.join('\n')||row.situacao)+'\nRDOs: '+(row.documentos.map(d=>String(d.numero)+' ['+String(d.id)+'] — '+String(d.situacao)+' — '+String(d.horas)+'h').join('; ')||'nenhum nesta linha'):'Selecione uma linha para conferir os documentos e registrar uma revisão.';$('mcf-history').textContent=row?list.filter(x=>x.key===row.key).map(x=>x.em+' — '+x.autor+' — '+x.decisao+'\n'+x.justificativa+'\n'+(x.signature===row.signature?'Mesmos dados comparados':'Dados comparados mudaram')).join('\n\n')||'Sem revisão anterior.':'';$('mcf-review').disabled=!row||busy;}
function render(){const rows=visible();$('mcf-rows').replaceChildren();for(const r of rows){const tr=document.createElement('tr'),td=document.createElement('td'),radio=document.createElement('input');radio.type='radio';radio.name='mcf-selected';radio.value=r.key;radio.checked=selected===r.key;radio.setAttribute('aria-label','Revisar '+r.nome+' em '+r.data+' na obra '+r.obra);radio.onchange=()=>{selected=r.key;$('mcf-reason').value='';details();};td.append(radio);tr.append(td);for(const value of [r.data,r.nome+' / '+r.funcionarioId,r.obra,r.planejado,r.frequencia,r.rdoAprovado,r.rdoRascunho,r.statusFrequencia+' — '+r.situacao+(r.motivos.length?' — '+r.motivos.join('; '):''),C.reviewState(r,list)]){const cell=document.createElement('td');cell.textContent=String(value);tr.append(cell);}$('mcf-rows').append(tr);}if(!rows.some(x=>x.key===selected))selected=null;details();say(rows.length+' linha(s) visível(is); '+rows.filter(x=>x.situacao==='Conferir divergência').length+' com divergência. Revisar não altera os lançamentos.');}
function options(id,values,first){const select=$(id),old=select.value;select.replaceChildren(new Option(first,''));for(const [value,label] of values)select.add(new Option(label,value));if([...select.options].some(o=>o.value===old))select.value=old;}
function refresh(){report=null;selected=null;list=[];snap=null;reviewSnapshot=null;$('mcf-rows').replaceChildren();$('mcf-warnings').textContent='';details();P.guard(localStorage,J.KEYS.rdos);const before=current();const result=C.build({plans:J.read(localStorage,J.KEYS.plans,[]),frequency:getFrequenciaDiariaDb(),rdos:getDb(),employees:J.read(localStorage,'cm_colaboradores_db',[]),start:$('mcf-start').value,end:$('mcf-end').value});const history=C.reviews(localStorage);if(P.canonical(current())!==P.canonical(before))throw Error('Fontes mudaram durante a leitura. Atualize a conferência.');report=result;list=history;snap=before;reviewSnapshot=localStorage.getItem(C.KEY);options('mcf-person',[...new Map(result.lines.map(r=>[r.funcionarioId,r.nome+' / '+r.funcionarioId]))].sort((a,b)=>a[1].localeCompare(b[1])),'Todos');options('mcf-work',[...new Set(result.lines.map(r=>r.obra))].sort().map(x=>[x,x]),'Todas');$('mcf-warnings').textContent=result.warnings.join('\n');$('mcf-reason').value='';render();}
$('mcf-day').onclick=run(()=>{$('mcf-start').value=$('mj-day').value;$('mcf-end').value=$('mj-day').value;refresh();});$('mcf-update').onclick=run(refresh);for(const id of ['mcf-person','mcf-work','mcf-only'])$(id).onchange=render;
$('mcf-review').onclick=async()=>{if(busy)return;busy=true;details();try{await P.withLock(navigator.locks,()=>{unchanged();let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const row=report.lines.find(r=>r.key===selected);if(!row)throw Error('Selecione uma linha');C.review(localStorage,report,row.key,row.signature,{user:currentLoggedUser,session,decisao:$('mcf-decision').value,justificativa:$('mcf-reason').value,expected:reviewSnapshot});list=C.reviews(localStorage);reviewSnapshot=localStorage.getItem(C.KEY);});$('mcf-reason').value='';render();say('Revisão registrada no histórico local. As divergências e as três fontes foram preservadas.');}catch(e){say(e.message);}finally{busy=false;details();}};
$('mcf-csv').onclick=run(()=>{unchanged();if(!report)throw Error('Atualize a conferência');const url=URL.createObjectURL(new Blob([C.csv({...report,lines:visible()},list)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='martins_conferencia_'+report.start+'_'+report.end+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('CSV da conferência filtrada gerado. Nenhuma fonte foi alterada.');});
$('mcf-start').value=$('mcf-end').value=new Date().toLocaleDateString('en-CA');$('mcf-review').disabled=true;window.addEventListener('storage',event=>{if(report&&(event.key===null||sources.includes(event.key)||event.key===C.KEY||event.key===P.KEY))say('Dados alterados em outra aba. Atualize a conferência antes de registrar ou exportar.');});
})();
